	public void unAssignTransaction( UnAssignTransactionFromChargebackCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignTransaction(command.getChargebackId());
	}
	




